<template>
  <div class="report-panel">
    <el-alert class="flow-alert" type="info" :closable="false" :title="`${isSow ? '播种' : '收获'}进度按已下达计划维护；每次保存都会形成一条记录并累加到当前计划。`" />

    <div class="panel toolbar-panel">
      <el-form :inline="true" class="filters"><el-form-item label="年份"><el-select v-model="filters.year" style="width:120px" @change="loadAll"><el-option v-for="item in years" :key="item" :label="`${item}年`" :value="item" /></el-select></el-form-item><el-form-item label="周期"><el-select v-model="filters.quarter" style="width:130px" @change="loadAll"><el-option v-for="item in quarters" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-button type="primary" @click="loadAll">刷新</el-button></el-form>
      <span class="scope-label">当前范围：{{ role.regionName || '安徽省' }}</span>
    </div>

    <div class="metric-grid"><div class="metric-card"><span>当前计划</span><strong>{{ selectedPlan?.planName || '请选择计划' }}</strong><small>{{ selectedPlan ? `${selectedPlan.planArea.toLocaleString()} 亩` : '按计划填写' }}</small></div><div class="metric-card blue"><span>累计{{ isSow ? '已播' : '已收获' }}</span><strong>{{ cumulativeDone.toLocaleString() }}</strong><small>本次新增 {{ form.increment.toLocaleString() }} 亩</small></div><div class="metric-card green"><span>{{ isSow ? '播种' : '收获' }}进度</span><strong>{{ cumulativeProgress }}%</strong><small>累计 / 计划</small></div><div class="metric-card orange"><span>填报记录</span><strong>{{ historyRows.length }}</strong><small>仅统计当前类型</small></div></div>

    <div class="panel plan-panel"><div class="panel-title"><span class="title-text">选择填报计划</span><span class="title-extra">播种和收获分别维护</span></div><div class="plan-grid"><button v-for="plan in planOptions" :key="plan.planId" class="plan-option" :class="{active:selectedPlanId===plan.planId}" @click="selectPlan(plan)"><b>{{ plan.planName }}</b><span>{{ plan.cropName }} · 计划 {{ plan.planArea.toLocaleString() }} 亩</span><em>累计 {{ plan.doneArea.toLocaleString() }} 亩</em></button></div><el-empty v-if="!planOptions.length" description="当前范围暂无可填报计划" :image-size="55" /></div>

    <div class="panel history-panel"><div class="panel-title"><span class="title-text">{{ isSow ? '播种' : '收获' }}进度填报记录</span><div class="title-actions"><el-button v-if="selectedPlan && canReport" type="primary" size="small" @click="openReport">填报{{ isSow ? '播种' : '收获' }}进度</el-button><el-tag size="small" type="info">{{ historyRows.length }} 条</el-tag></div></div><el-table :data="historyRows" stripe border max-height="280"><el-table-column prop="planName" label="对应计划" min-width="220" show-overflow-tooltip /><el-table-column prop="updatedAt" label="填报时间" width="130" /><el-table-column prop="increment" label="本次新增（亩）" width="140" align="right" /><el-table-column prop="cumulative" :label="`累计${isSow ? '已播' : '已收获'}（亩）`" width="160" align="right" /><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="statusType(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="乡镇/主体明细" min-width="180"><template #default="{row}">{{ (row.details || []).map(item => `${item.name} ${item.area}亩`).join('、') || '未填写明细' }}</template></el-table-column><template #empty><el-empty description="暂无本类型填报记录" /></template></el-table></div>

    <el-dialog v-model="reportVisible" :title="`填写本次${isSow ? '播种' : '收获'}进度`" width="min(900px, 94vw)" destroy-on-close><div v-if="selectedPlan" class="report-dialog-body"><div class="selected-plan-summary"><b>{{ selectedPlan.planName }}</b><span>计划面积 {{ selectedPlan.planArea.toLocaleString() }} 亩 · 累计{{ isSow ? '已播' : '已收获' }} {{ cumulativeDone.toLocaleString() }} 亩 · 剩余 {{ remainingArea.toLocaleString() }} 亩</span></div><el-form :inline="true" class="progress-form"><el-form-item label="计划面积（亩）"><el-input-number :model-value="selectedPlan.planArea" disabled /></el-form-item><el-form-item :label="`累计${isSow ? '已播' : '已收获'}（亩）`"><el-input-number :model-value="cumulativeDone" disabled /></el-form-item><el-form-item label="本次新增（亩）"><el-input-number v-model="form.increment" :min="0" :max="remainingArea" :precision="1" controls-position="right" /></el-form-item></el-form><div class="town-detail-box"><div class="panel-title"><span class="title-text">{{ roleCode === 'county' ? '乡镇进度明细' : '主体进度明细' }}</span><el-button size="small" type="primary" plain @click="addDetail">添加{{ roleCode === 'county' ? '乡镇' : '主体' }}</el-button></div><div class="detail-table-head"><span>{{ roleCode === 'county' ? '乡镇名称' : '种植主体' }}</span><span>本次新增面积（亩）</span><span>操作</span></div><div v-for="row in form.details" :key="row.id" class="detail-row"><el-select v-if="roleCode === 'county'" v-model="row.name" placeholder="请选择乡镇" filterable><el-option v-for="town in townOptions" :key="town.code" :label="town.name" :value="town.name" /></el-select><el-input v-else v-model="row.name" :placeholder="`输入${roleCode === 'county' ? '乡镇' : '主体'}名称`" /><el-input-number v-model="row.area" :min="0" :precision="1" controls-position="right" /><el-button link type="danger" @click="removeDetail(row)">删除</el-button></div><el-empty v-if="!form.details.length" :description="`可选填${roleCode === 'county' ? '乡镇' : '主体'}明细`" :image-size="42" /></div></div><template #footer><span class="dialog-tip">提交后进入{{ roleCode === 'county' ? '市级' : roleCode === 'town' ? '县级' : '上级' }}审核；审核通过后计入正式累计。</span><el-button @click="reportVisible=false">取消</el-button><el-button type="primary" @click="saveProgress">提交并送审</el-button></template></el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { fetchProgressReportRows, fetchProgressReportOrders, saveSowingProgress, saveHarvestProgress, submitProgressReport } from '@/api/gpm'
import { useUserStore } from '@/stores/user'
import { listTowns } from '@/mock/common/regions'
const props = defineProps({ type: { type: String, default: 'sow' } }); const userStore = useUserStore(); const role = computed(() => userStore.role || {}); const roleCode = computed(() => role.value.code || ''); const isSow = computed(() => props.type === 'sow'); const canReport = computed(() => ['county', 'town'].includes(roleCode.value)); const years = [2026, 2025, 2024]; const quarters = ['全年', '第一季度', '第二季度', '第三季度', '第四季度']; const filters = reactive({ year: 2026, quarter: '第三季度' }); const rows = ref([]); const selectedPlanId = ref(''); const historyRows = ref([]); const reportVisible = ref(false); const form = reactive({ increment: 0, details: [] })
const storageKey = computed(() => `pc-progress-history-${props.type}-${role.value.regionCode || '340000'}`)
const townOptions = computed(() => roleCode.value === 'county' ? listTowns(role.value.regionCode || '341222') : [])
const planOptions = computed(() => { const map = new Map(); rows.value.filter(x => Number(x.year) === Number(filters.year) && (!filters.quarter || filters.quarter === '全年' || x.quarter === filters.quarter)).forEach(item => { const id = item.planId || item.planName || `${item.year}-${item.quarter}-${item.cropName || item.crop}`; const old = map.get(id) || { planId: id, planName: item.planName || `${item.year}年${item.quarter}${item.cropName || item.crop}计划`, cropName: item.cropName || item.crop || '粮食作物', planArea: Number(item.planArea || 0), doneArea: 0 }; old.planArea = Math.max(old.planArea, Number(item.planArea || 0)); old.doneArea = Math.max(old.doneArea, Number(item[isSow.value ? 'sownArea' : 'harvestedArea'] || item.reportedArea || 0)); map.set(id, old) }); historyRows.value.forEach(item => { const current = map.get(item.planId); if (current) current.doneArea = Math.max(current.doneArea, Number(item.cumulative || 0)) }); return [...map.values()].filter(x => x.planArea > 0) })
const selectedPlan = computed(() => planOptions.value.find(x => x.planId === selectedPlanId.value) || planOptions.value[0] || null); const cumulativeDone = computed(() => Number(selectedPlan.value?.doneArea || 0)); const remainingArea = computed(() => Math.max(0, Number(selectedPlan.value?.planArea || 0) - cumulativeDone.value)); const cumulativeProgress = computed(() => selectedPlan.value?.planArea ? Number(Math.min(100, cumulativeDone.value / selectedPlan.value.planArea * 100).toFixed(1)) : 0)
const selectPlan = plan => { selectedPlanId.value = plan.planId; form.increment = 0; form.details = [] }
const openReport = () => { if (!selectedPlan.value) return ElMessage.warning('请先选择填报计划'); form.increment = 0; form.details = []; reportVisible.value = true }
const statusLabel = status => ({ '待审核': roleCode.value === 'county' ? '待市级审核' : roleCode.value === 'town' ? '待县级审核' : '待上级审核', '审核通过': '审核通过', '已驳回': '已退回' }[status] || status || (roleCode.value === 'county' ? '待市级审核' : '待上级审核'))
const statusType = status => ({ '待审核': 'warning', '审核通过': 'success', '已驳回': 'danger' }[status] || 'info')
const addDetail = () => form.details.push({ id: `detail-${Date.now()}-${form.details.length}`, name: roleCode.value === 'county' ? (townOptions.value[0]?.name || '') : '', area: 0 })
const removeDetail = row => { form.details = form.details.filter(x => x !== row) }
const loadAll = async () => { rows.value = await fetchProgressReportRows(role.value, { type: props.type, year: filters.year, quarter: filters.quarter }); let localRows = []; try { localRows = JSON.parse(localStorage.getItem(storageKey.value) || '[]') } catch { localRows = [] } const orders = await fetchProgressReportOrders(role.value, { type: props.type, year: filters.year, quarter: filters.quarter, includeOwn: true }); const orderRows = orders.map(order => ({ id: order.id, planId: order.planId, planName: order.planName || `${order.year}年${order.quarter}${isSow.value ? '播种' : '收获'}进度`, year: order.year, quarter: order.quarter, increment: Number(order.submittedSummary?.increment || 0), cumulative: Number(order.submittedSummary?.cumulative || 0), details: order.details || [], updatedAt: order.reportedAt || '', status: order.status || '待审核' })); const merged = new Map(); [...orderRows, ...localRows].forEach(item => { if (!merged.has(item.id)) merged.set(item.id, item); else merged.set(item.id, { ...merged.get(item.id), ...item }) }); historyRows.value = [...merged.values()].sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || ''))); if (!selectedPlanId.value && planOptions.value.length) selectedPlanId.value = planOptions.value[0].planId }
const saveProgress = async () => { if (!selectedPlan.value) return ElMessage.warning('请先选择填报计划'); const increment = Number(form.increment || 0); if (increment <= 0) return ElMessage.warning('请填写本次新增面积'); if (increment > remainingArea.value) return ElMessage.warning('本次新增面积不能超过计划剩余面积'); if (form.details.some(x => !x.name || Number(x.area || 0) < 0)) return ElMessage.warning('请完整填写明细名称和面积'); const cumulative = cumulativeDone.value + increment; const payload = { planId: selectedPlan.value.planId, planName: selectedPlan.value.planName, regionCode: role.value.regionCode, regionName: role.value.regionName, crop: selectedPlan.value.cropName, cropName: selectedPlan.value.cropName, planArea: selectedPlan.value.planArea, year: filters.year, quarter: filters.quarter, progressIncrement: increment, details: form.details.map(x => ({ ...x })), ...(isSow.value ? { sownArea: cumulative } : { harvestedArea: cumulative }) }; const result = isSow.value ? await saveSowingProgress(payload, role.value) : await saveHarvestProgress(payload, role.value); if (!result.success) return ElMessage.error(result.message || '保存失败'); const submitted = await submitProgressReport(role.value, { ...payload, type: props.type }); if (!submitted.success) return ElMessage.error(submitted.message || '已保存进度，但提交审核失败'); const next = { id: submitted.item?.id || `PC-${props.type}-${Date.now()}`, planId: selectedPlan.value.planId, planName: selectedPlan.value.planName, year: filters.year, quarter: filters.quarter, increment, cumulative, details: form.details.map(x => ({ ...x })), status: submitted.item?.status || '待审核', updatedAt: new Date().toISOString().slice(0, 10) }; historyRows.value = [next, ...historyRows.value]; localStorage.setItem(storageKey.value, JSON.stringify(historyRows.value)); ElMessage.success('本次进度已提交，等待市级审核'); reportVisible.value = false; form.increment = 0; form.details = []; await loadAll() }
onMounted(loadAll)
</script>

<style lang="scss" scoped>
.report-panel{display:flex;flex-direction:column;gap:12px;min-height:100%;box-sizing:border-box;padding-bottom:20px}.flow-alert :deep(.el-alert__title){font-size:13px}.toolbar-panel{display:flex;align-items:center;justify-content:space-between;flex-shrink:0}.toolbar-panel .filters{display:flex;align-items:center;margin:0}.toolbar-panel :deep(.el-form-item){margin:0 12px 0 0}.scope-label{color:#606266;font-size:13px}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;flex-shrink:0}.metric-card{padding:14px 16px;background:#fff;border-left:4px solid #8a97a8;border-radius:8px;box-shadow:0 1px 4px rgba(15,62,120,.06)}.metric-card.blue{border-color:var(--ah-primary,#1668DC)}.metric-card.green{border-color:var(--ah-success,#2d8c72)}.metric-card.orange{border-color:#d9942d}.metric-card span,.metric-card small{display:block;color:var(--ah-text-secondary,#718096);font-size:12px}.metric-card strong{display:block;margin:5px 0 2px;font-size:20px;color:var(--ah-text,#1f2937);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.panel{background:#fff;border:1px solid #e8edf3;border-radius:8px;padding:16px}.panel-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.title-text{font-weight:600;color:var(--ah-text,#1f2937)}.title-extra{color:var(--ah-text-secondary,#718096);font-size:12px}.plan-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.plan-option{border:1px solid #d9e2ec;border-radius:8px;background:#fff;padding:12px;text-align:left;min-height:92px}.plan-option.active{border-color:#1668dc;background:#eef5ff;box-shadow:0 0 0 1px #1668dc inset}.plan-option b,.plan-option span,.plan-option em{display:block}.plan-option b{color:#243b5a;font-size:14px}.plan-option span{color:#667085;font-size:12px;margin-top:7px}.plan-option em{color:#176b58;font-size:12px;font-style:normal;margin-top:7px}.progress-form{display:flex;align-items:center;flex-wrap:wrap;gap:10px}.town-detail-box{margin-top:8px;padding:12px;background:#fbfdff;border:1px solid #e5ebf2;border-radius:8px}.detail-table-head{display:grid;grid-template-columns:minmax(220px,1fr) 160px 54px;gap:10px;align-items:center;padding:8px 0;color:#98a2b3;font-size:12px;border-bottom:1px solid #dfe7ef}.detail-table-head span:nth-child(2){text-align:right}.detail-table-head span:last-child{text-align:right}.detail-row{display:grid;grid-template-columns:minmax(220px,1fr) 160px 54px;align-items:center;gap:10px;border-top:1px solid #edf0f5;padding:9px 0}.detail-row :deep(.el-input),.detail-row :deep(.el-select){width:100%}.detail-row :deep(.el-input-number){width:160px}.detail-row :deep(.el-button){justify-self:end;padding:0}.entry-actions{display:flex;align-items:center;justify-content:space-between;margin-top:12px;padding-top:12px;border-top:1px solid #edf0f5;color:#667085;font-size:13px}.title-actions{display:flex;align-items:center;gap:10px}.report-dialog-body{max-height:62vh;overflow:auto;padding:2px 4px 8px}.selected-plan-summary{display:flex;flex-direction:column;gap:5px;padding:12px 14px;margin-bottom:16px;background:#f4f8ff;border-left:3px solid #1668dc;border-radius:6px;color:#243b5a}.selected-plan-summary span{font-size:12px;color:#667085}.dialog-tip{margin-right:auto;color:#667085;font-size:12px}.progress-cell{display:flex;align-items:center;gap:8px}.progress-cell :deep(.el-progress){flex:1}.progress-cell span{width:44px;color:#606266;text-align:right;font-size:12px}@media (max-width:1100px){.metric-grid{grid-template-columns:repeat(2,1fr)}}
</style>